# Batch 07 — Chapter VII, Sections 1–2 (Articles 60–67): cooperation and consistency.
def rt(u, origin, cp, rtype, obj, fn, mod, cond="", note="", deriv="direct", unres="", flag="", acc="", ext_dep="", dep=""):
    return qr(u, origin, cp, rtype, obj, fn, mod, cond=cond, deriv=deriv, type_note=note, unresolved=unres, flag=flag, acc=acc, ext=ext_dep, dep=dep)
CTRL, PROC, DS, SA, COMMN, MS = "controller", "processor", "data subject", "supervisory authority", "European Commission", "Member States"
LSA_, SAC = "lead supervisory authority", "supervisory authority concerned"
BD = "European Data Protection Board"
P60 = pd("lead-authority cooperation procedure (Art.60)", "device", "A60.P1;A60.P3;A60.P4;A60.P5;A60.P6;A60.P7", ntype="N0 (procedure rules set out directly; no 'hereby established')", note="Procedure with identity (Art.60), operators (lead and concerned SAs) and rules (deadlines, objection, deemed agreement).", flag="DEV-threshold")
P61 = pd("mutual assistance (Art.61)", "device", "A61.P1;A61.P2", ntype="N0 (procedure rules set out directly)", note="Procedure among SAs; identity, rules (one month, grounds for refusal), operators.", flag="DEV-threshold")
P62 = pd("joint operations (Art.62)", "device", "A62.P1;A62.P2", ntype="N0 (procedure rules set out directly)", note="Procedure among SAs with right to participate.", flag="DEV-threshold")
CM = pd("consistency mechanism (Art.63)", "device", "A63.P0;A64.P1;A65.P1;A66.P1;A67.P0", ntype="N0 (mechanism 'as set out in this Section'; rules set out directly in Arts 64–67; not 'hereby established')", note="Bundle of procedures (opinion of the Board, dispute resolution, urgency procedure, information exchange) operated by SAs, the Board and the Commission.", flag="DEV-threshold")
P66 = pd("urgency procedure (Art.66)", "device", "A66.P1;A66.P2;A66.P3;A66.P4", ntype="N0 (procedure rules set out directly)", note="Derogation from Arts 60 and 63–65.", flag="DEV-threshold")
CHAIR = pd("Chair of the Board", "position_type", "A64.P5;A68.P2", note="Office within the Board (Arts 73–74).")
EDPS = pd("European Data Protection Supervisor", "position_type", "A68.P3", ntype="constituted outside W (external reference)", note="Member of the Board and provider of its secretariat; its constitution lies in another instrument (see Art.2(3)).", flag="external-constitution")

# ---- Article 60
q = [rt("A60.P1", LSA_, SAC + "s", "information/reporting", "cooperation in an endeavour to reach consensus; exchange of all relevant information (mutual)", "cooperation/coordination", "obligation", note="peer-style cooperation under the lead authority; gov-direction: LSA coordinates"),
     rt("A60.P1", SAC, LSA_, "information/reporting", "exchange of all relevant information", "information provision", "obligation")]
screen("A60.P1", "Yes", "relation-bearing", qr=q, pos=[P60], status="Extracted")
q = [rt("A60.P2", LSA_, SAC + "s", "information/reporting", "request for mutual assistance (Art.61) and conduct of joint operations (Art.62)", "cooperation/coordination", "permission", cond="at any time; in particular for investigations or monitoring implementation of a measure concerning a controller/processor established in another Member State", dep="Arts 61–62")]
screen("A60.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A60.P3", LSA_, SAC + "s", "representation/participation", "communication of relevant information; submission of a draft decision for opinion; taking due account of their views", "consultation", "obligation", cond="without delay", note="gov-direction: LSA consults concerned SAs; duty to take due account")]
screen("A60.P3", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A60.P4", SAC, LSA_, "review/adjudication", "relevant and reasoned objection to the draft decision within four weeks", "participation (objection)", "competence", cond="within four weeks after consultation", note="objection right of concerned SAs; objection defined in Art.4(24)"),
     rt("A60.P4", LSA_, BD + " (via the consistency mechanism)", "review/adjudication", "submission of the matter to the consistency mechanism (Art.63)", "cooperation/coordination (escalation)", "obligation", cond="the lead authority does not follow the relevant and reasoned objection or considers it not relevant or reasoned", dep="consistency mechanism (Art.63); Art.65(1)(a)", note="escalation duty; counterpart is the consistency mechanism whose decision-maker is the Board (Art.65)")]
screen("A60.P4", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="Objection and escalation: link to Art.65(1)(a) (binding decision of the Board).")
q = [rt("A60.P5", LSA_, SAC + "s", "representation/participation", "submission of a revised draft decision for their opinion, subject to the objection procedure within two weeks", "consultation", "obligation", cond="the lead authority intends to follow the relevant and reasoned objection")]
screen("A60.P5", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A60.P6", LSA_, SAC + "s", "authority/control", "deemed agreement with the draft decision and being bound by it", "decision (legal effect among SAs)", "declaratory", cond="none of the other concerned SAs has objected within the periods in 60(4),(5)", note="legal effect among peers: binding by tacit agreement")]
screen("A60.P6", "Yes", "relation-bearing", qr=q, status="Extracted", note="Tacit consent binds the authorities concerned.")
q = [rt("A60.P7", LSA_, CTRL + " / " + PROC + " (main or single establishment)", "authority/control", "adoption and notification of the decision to the main or single establishment", "enforcement/decision", "obligation", cond="after the procedure of 60(3)-(6)", note="gov-direction: LSA decides over controller/processor"),
     rt("A60.P7", LSA_, SAC + "s and the Board", "information/reporting", "information on the decision including a summary of the relevant facts and grounds", "information provision", "obligation", acc="INFO/ANSWERABILITY-candidate (reasons communicated to SAs and the Board; no questioning or assessment capacity stated in this unit)"),
     rt("A60.P7", SA + " with which a complaint was lodged", DS + " (complainant)", "information/reporting", "information to the complainant on the decision", "information provision", "obligation")]
screen("A60.P7", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A60.P8", SA + " with which a complaint was lodged", DS + " (complainant)", "review/adjudication", "adoption and notification of the decision dismissing or rejecting a complaint; information to the controller", "adjudication (administrative)", "obligation", cond="complaint dismissed or rejected; derogation from 60(7)"),
     rt("A60.P8", SA + " with which a complaint was lodged", CTRL, "information/reporting", "information on the dismissal/rejection decision", "information provision", "obligation")]
screen("A60.P8", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A60.P9", LSA_ + " and the SA of the complainant", CTRL + " / " + PROC + " and " + DS, "authority/control", "separate decisions for parts of a complaint: LSA decides on actions against the controller and informs the complainant; the complainant's SA decides on dismissal/rejection and informs the controller", "adjudication/decision allocation", "obligation", cond="parts of a complaint partly dismissed and partly acted on", note="split of decision-making between two SAs")]
screen("A60.P9", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A60.P10", CTRL + " / " + PROC, LSA_, "oversight/supervision", "necessary measures to comply with the decision as regards all establishments in the Union; notification of the measures taken to the lead authority, which informs the other concerned SAs", "implementation; information provision", "obligation", cond="after notification of the decision", note="gov-direction: LSA oversees compliance; the relation continues with LSA informing concerned SAs", acc="INFO/ANSWERABILITY-candidate (duty to notify measures to LSA; questioning/assessment capacity of the LSA stated elsewhere, Art.58)"),
     rt("A60.P10", LSA_, SAC + "s", "information/reporting", "information on the measures notified by the controller/processor", "information provision", "obligation")]
screen("A60.P10", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A60.P11", SAC, BD + " (urgency procedure)", "information/reporting", "application of the urgency procedure of Art.66 where there is an urgent need to protect data subjects", "cooperation/coordination (escalation)", "obligation", cond="exceptional circumstances; reasons to consider there is an urgent need to act", dep="urgency procedure (Art.66)")]
screen("A60.P11", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted")
screen("A60.P12", "No", "formal-requirement", status="Not applicable", note="Electronic exchange in standardised format.")

# ---- Article 61 (mutual assistance)
q = [rt("A61.P1", SA, SA + " (other)", "information/reporting", "relevant information and mutual assistance (information requests; supervisory measures such as prior authorisations and consultations, inspections and investigations); measures for effective cooperation", "cooperation/coordination", "obligation", note="reciprocal duty among all SAs", dep="mutual assistance procedure (Art.61)")]
screen("A61.P1", "Yes", "relation-bearing", qr=q, pos=[P61], status="Extracted")
q = [rt("A61.P2", SA + " (requested)", SA + " (requesting)", "information/reporting", "reply to a request without undue delay and no later than one month", "information provision", "obligation", cond="after receiving the request")]
screen("A61.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
screen("A61.P3", "No", "content-specification", status="Not applicable", note="Requests contain all necessary information; use limited to purpose.")
q = [rt("A61.P4", SA + " (requested)", SA + " (requesting)", "authority/control", "no refusal to comply with a request unless (a) not competent or (b) compliance would infringe the Regulation or applicable law", "cooperation/coordination (limit on refusal)", "prohibition (except)", cond="grounds (a) and (b)")]
screen("A61.P4", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A61.P5", SA + " (requested)", SA + " (requesting)", "information/reporting", "information on results or progress; reasons for any refusal", "information provision", "obligation", acc="ANSWERABILITY candidate (duty to inform and to give reasons for refusal to an identified forum; assessment and consequence in 61(8) and Art.66(2); questioning capacity not stated)", note="candidate accountability-like relation between peers")]
screen("A61.P5", "Yes", "relation-bearing", qr=q, status="Extracted", note="Reasons for refusal owed to the requesting SA.")
screen("A61.P6", "No", "formal-requirement", status="Not applicable", note="Electronic means, standardised format.")
screen("A61.P7", "No", "formal-requirement", status="Not applicable", note="No fee; possible indemnification rules agreed among SAs.")
q = [rt("A61.P8", SA + " (requesting)", SA + " (requested)", "authority/control", "adoption of a provisional measure on the territory of its Member State where no information on results/progress is provided within one month; urgent need under Art.66(1) is presumed and requires an urgent binding decision of the Board under Art.66(2)", "enforcement (provisional measure)", "competence", cond="requested SA has not provided the information within one month", dep="Art.55(1); Art.66(1),(2)", note="gov-direction: requesting SA may act on its own territory; escalation to the Board")]
screen("A61.P8", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="Consequence of non-assistance: provisional measure plus presumed urgency.")
n = na("A61.P9", COMMN, "specify by implementing acts the format and procedures for mutual assistance and the electronic exchange of information between SAs and between SAs and the Board", "format and procedures for mutual assistance", "rule-making (implementing)", "competence", cond="examination procedure of Art.93(2)", dep="Art.93(2) examination procedure", cp_status="none")
screen("A61.P9", "Yes", "operative-assignment (competence)", na=[n], status="Extracted")

# ---- Article 62 (joint operations)
q = [rt("A62.P1", SA, SA + " (of other Member States)", "representation/participation", "joint operations including joint investigations and joint enforcement measures involving members or staff of other SAs", "cooperation/coordination", "obligation", cond="where appropriate")]
screen("A62.P1", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A62.P2", SA + " (of each Member State concerned)", SA + " competent under Art.56(1) or (4)", "representation/participation", "right to participate in joint operations", "participation", "entitlement", cond="establishments in several Member States or a significant number of data subjects in more than one Member State substantially affected", note="entitlement of concerned SAs"),
     rt("A62.P2", SA + " competent under Art.56(1) or (4)", SA + " (of each Member State concerned)", "representation/participation", "invitation to take part and prompt response to participation requests", "participation", "obligation", note="duty correlative to the right")]
screen("A62.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A62.P3", SA + " (host)", SA + " (seconding)", "delegation/authorization", "conferral of powers, including investigative powers, on seconded members/staff, or permission for them to exercise their own powers, under the host's guidance and in its presence", "authorization (secondment)", "permission", cond="in accordance with Member State law; with the seconding authority's authorisation; so far as host law permits", note="seconded staff subject to host Member State law")]
screen("A62.P3", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A62.P4", MS + " (host)", "damage caused by seconded staff", "contractual/exchange", "responsibility, including liability, for the actions of seconded staff during operations in its territory", "remediation (liability allocation)", "obligation", cond="seconded staff operate in another Member State; in accordance with the law of that Member State", note="liability allocation among Member States")]
screen("A62.P4", "Yes", "relation-bearing", qr=q, status="Extracted", note="Counterpart is not a position (damage); relation recorded as a liability allocation among Member States.")
q = [rt("A62.P5", MS + " (in whose territory the damage was caused)", MS + " (of the seconding SA)", "contractual/exchange", "making good the damage; full reimbursement by the seconding Member State of sums paid", "remediation (liability allocation)", "obligation")]
screen("A62.P5", "Yes", "relation-bearing", qr=q, status="Extracted")
screen("A62.P6", "No", "limitation", status="Not applicable", note="Member States refrain from reimbursement requests among themselves (except 62(5)).")
q = [rt("A62.P7", SA + " (other, in the joint operation)", SA + " (not complying)", "authority/control", "adoption of a provisional measure on the territory of the non-complying authority's Member State; urgent need presumed; opinion or urgent binding decision of the Board under Art.66(2)", "enforcement (provisional measure)", "competence", cond="the non-complying SA fails within one month to comply with the invitation/response duty of 62(2)", dep="Art.55; Art.66(1),(2)", note="gov-direction: peer SAs may act against a non-complying SA's territory; ambiguity: 'its Member State' read as that of the non-complying SA", unres="reference of 'its Member State' to the non-complying SA is an interpretation", flag="interpretation")]
screen("A62.P7", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="See UNC for the referent of 'its Member State'.")
unc("A62.P7", "interpretation", "'a provisional measure on the territory of its Member State' — referent of 'its' (non-complying SA's Member State vs the adopting SA's) is ambiguous in the text", "affects the direction of the peer-enforcement relation in 62(7)", "")

# ---- Article 63, 64, 65, 66, 67
n = na("A63.P0", SA + "s (and, where relevant, the Commission)", "cooperate with each other, and where relevant with the Commission, through the consistency mechanism as set out in Section 2, to contribute to consistent application", "consistent application", "cooperation/coordination", "obligation", dep="consistency mechanism (Art.63)", cp_status="none", note="Names the mechanism and refers to Section 2 for its rules; the mechanism is set out, not 'established'.")
screen("A63.P0", "Yes", "operative-assignment; device-referencing", na=[n], pos=[CM], status="Extracted", note="Consistency mechanism: identity and rules in Arts 64–67; DEV threshold flagged.")
q = [rt("A64.P1", SA + " (competent)", BD, "information/reporting", "communication of the draft decision to the Board before adopting: DPIA lists (35(4)); matters under 40(7) on codes of conduct; accreditation requirements (41(3), 43(3)) and certification criteria (42(5)); standard data protection clauses (46(2)(d), 28(8)); contractual clauses (46(3)(a)); binding corporate rules (Art.47)", "cooperation/coordination (consistency)", "obligation", cond="the SA intends to adopt one of measures (a)-(f); corrigendum 2018: point (c) now includes 'requirements' for accreditation and 'criteria for certification'", dep="consistency mechanism (Art.63)", note="Links Arts 35, 40, 41, 42, 43, 46, 28 and 47 to the Board (cross-chapter coupling)"),
     rt("A64.P1", BD, SA + " (competent)", "verification/assurance", "issue of an opinion on the draft decision", "verification/assurance (opinion)", "obligation", cond="the competent SA intends to adopt one of the measures (a)-(f)", dep="consistency mechanism (Art.63)", note="gov-direction: Board assesses draft decisions of SAs")]
screen("A64.P1", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="Corrigendum applied at point (c). Six listed measures tie Chapter IV instruments to the Board.")
q = [rt("A64.P2", SA + " / Chair of the Board / " + COMMN, BD, "information/reporting", "request that a matter of general application or producing effects in more than one Member State be examined by the Board for an opinion", "cooperation/coordination (referral)", "permission", cond="in particular where a competent SA does not comply with mutual assistance (Art.61) or joint operations (Art.62)", dep="consistency mechanism (Art.63)")]
screen("A64.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
n = na("A64.P3", BD, "issue an opinion on matters submitted under 64(1),(2) within eight weeks by simple majority (extendable by six weeks), provided no opinion on the same matter has been issued; a member not objecting within a reasonable period is deemed to agree", "opinion of the Board", "verification/assurance (opinion)", "obligation", cond="matter submitted; opinion not already issued", cp_status="none", dep="consistency mechanism (Art.63)")
screen("A64.P3", "Yes", "operative-assignment", na=[n], status="Extracted")
q = [rt("A64.P4", SA + " and the Commission", BD, "information/reporting", "communication by electronic means in a standardised format of relevant information (summary of facts, the draft decision, the grounds, the views of other SAs concerned)", "information provision", "obligation", cond="without undue delay")]
screen("A64.P4", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A64.P5", CHAIR, "members of the Board and the Commission", "information/reporting", "information on any relevant information communicated to the Board", "information provision", "obligation", cond="without undue delay"),
     rt("A64.P5", CHAIR, SA + " (referred to in 64(1),(2)) and the Commission", "information/reporting", "information on the opinion and its publication", "information provision", "obligation")]
screen("A64.P5", "Yes", "relation-bearing", qr=q, pos=[CHAIR], status="Extracted")
q = [rt("A64.P6", BD, SA + " (competent)", "authority/control", "standstill: the competent SA shall not adopt its draft decision within the period for the opinion", "decision (suspensive effect)", "prohibition", cond="period of 64(3); corrigendum 2018: 'competent supervisory authority referred to in paragraph 1'", note="gov-direction: Board's procedure suspends the SA's decision-making")]
screen("A64.P6", "Yes", "relation-bearing", qr=q, status="Extracted", note="Corrigendum applied.")
q = [rt("A64.P7", SA + " (competent)", BD + " (Chair)", "information/reporting", "utmost account of the opinion; within two weeks, communication of whether the draft decision is maintained or amended, with any amended draft", "information provision; consideration", "obligation", cond="after receiving the opinion; corrigendum 2018: 'competent supervisory authority referred to in paragraph 1'", acc="ANSWERABILITY candidate (duty to take utmost account and to state whether the opinion is followed; grounds required in 64(8) if not followed)")]
screen("A64.P7", "Yes", "relation-bearing", qr=q, status="Extracted", note="Corrigendum applied.")
q = [rt("A64.P8", SA + " (competent)", BD + " (Chair)", "information/reporting", "information that the SA does not intend to follow the opinion in whole or in part, with the relevant grounds; Art.65(1) then applies", "information provision (reasons)", "obligation", cond="within the period in 64(7)", dep="Art.65(1)(c)", acc="ANSWERABILITY (actor SA; forum Board; duty to give relevant grounds; assessment/judgment and binding consequence in Art.65(1)(c); questioning capacity not stated) — see AI register", note="corrigendum 2018 applied")]
screen("A64.P8", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="Duty to give grounds for not following the Board's opinion; escalation to binding decision.")
q = [rt("A65.P1", BD, SA + " (lead and concerned)", "review/adjudication", "binding decision in individual cases: (a) objection under Art.60(4) not followed or rejected; (b) conflicting views on which SA is competent for the main establishment; (c) competent SA does not request an opinion or does not follow it", "adjudication/dispute resolution (binding decision)", "competence", cond="cases (a)-(c); corrigendum 2018 at (a): 'has not followed the objection or has rejected'", dep="consistency mechanism (Art.63); Art.60(4); Art.64", note="gov-direction: Board decides disputes among SAs; binding on them (65(2))"),
     rt("A65.P1", SAC + " or the " + COMMN, BD, "information/reporting", "communication of the matter to the Board in case (c)", "cooperation/coordination (referral)", "permission", cond="competent SA did not request an opinion or did not follow it")]
screen("A65.P1", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="Corrigendum applied at (a). Binding dispute resolution by the Board.")
q = [rt("A65.P2", BD, LSA_ + " and all SAs concerned", "authority/control", "reasoned binding decision adopted within one month by a two-thirds majority (extendable by one month), addressed to the LSA and all SAs concerned", "decision (binding)", "obligation", cond="after referral", note="binding on the addressees")]
screen("A65.P2", "Yes", "relation-bearing", qr=q, status="Extracted")
n = na("A65.P3", BD, "adopt its decision within two weeks after the second month by simple majority; the Chair's vote decides if split", "decision procedure", "decision procedure", "obligation", cp_status="none", cond="Board unable to decide within the 65(2) periods")
screen("A65.P3", "Yes", "operative-assignment (procedural)", na=[n], status="Extracted")
q = [rt("A65.P4", BD + " (procedure)", SAC + "s", "authority/control", "standstill: the SAs concerned shall not adopt a decision on the matter during the periods", "decision (suspensive effect)", "prohibition", cond="periods in 65(2),(3)")]
screen("A65.P4", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A65.P5", CHAIR, SAC + "s and the Commission", "information/reporting", "notification of the decision; information to the Commission; publication on the Board's website after the SA notifies its final decision", "information provision", "obligation")]
screen("A65.P5", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A65.P6", LSA_ + " (or the SA with which the complaint was lodged)", CTRL + " / " + PROC + " and " + DS, "authority/control", "final decision on the basis of the Board's binding decision within one month, referring to and attaching it", "decision (binding on LSA)", "obligation", cond="Board has notified its decision; Art.60(7),(8),(9) apply", note="final decision remains the LSA's act but is bound by the Board's decision"),
     rt("A65.P6", LSA_ + " (or the SA with which the complaint was lodged)", BD, "information/reporting", "information on the date the final decision is notified to the controller/processor and to the data subject", "information provision", "obligation", acc="INFO (information on date; no justification or questioning capacity stated)")]
screen("A65.P6", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A66.P1", SAC, SA + "s concerned, the Board and the " + COMMN, "information/reporting", "communication of provisional measures (not exceeding three months) and the reasons for adopting them", "information provision (reasons)", "obligation", cond="exceptional circumstances; urgent need to protect data subjects; derogation from Arts 60 and 63–65", dep="urgency procedure (Art.66)", acc="ANSWERABILITY candidate (reasons communicated to SAs, Board and Commission; assessment/consequence via Art.66(2)-(4); questioning not stated)"),
     rt("A66.P1", SAC, "(own territory)", "authority/control", "immediate adoption of provisional measures producing legal effects on its own territory, valid up to three months", "enforcement (provisional measure)", "competence", cond="exceptional circumstances; derogation from consistency mechanism and Art.60", note="gov-direction: SA acts unilaterally; reasons communicated")]
screen("A66.P1", "Yes", "relation-bearing; procedural-dependency", qr=q, pos=[P66], status="Extracted")
q = [rt("A66.P2", SA, BD, "information/reporting", "request for an urgent opinion or urgent binding decision giving reasons", "cooperation/coordination (referral)", "permission", cond="SA has taken a measure under 66(1) and considers final measures urgently needed"),
     rt("A66.P3", SA + " (any)", BD, "information/reporting", "request for an urgent opinion or binding decision giving reasons, including the urgent need to act", "cooperation/coordination (referral)", "permission", cond="a competent SA has not taken an appropriate measure in an urgent situation")]
screen("A66.P2", "Yes", "relation-bearing", qr=[q[0]], status="Extracted")
screen("A66.P3", "Yes", "relation-bearing", qr=[q[1]], status="Extracted")
n = na("A66.P4", BD, "adopt an urgent opinion or urgent binding decision within two weeks by simple majority (derogation from Arts 64(3) and 65(2))", "urgent opinion/decision", "decision procedure", "obligation", cp_status="none", cond="requests under 66(2),(3)")
screen("A66.P4", "Yes", "operative-assignment (procedural)", na=[n], status="Extracted")
n = na("A67.P0", COMMN, "adopt implementing acts of general scope specifying the arrangements for the exchange of information by electronic means between SAs and between SAs and the Board, in particular the standardised format in Art.64", "information-exchange arrangements", "rule-making (implementing)", "competence", cond="examination procedure of Art.93(2)", dep="Art.93(2) examination procedure", cp_status="none")
screen("A67.P0", "Yes", "operative-assignment (competence)", na=[n], status="Extracted")
